void g_PlayerSprites_SetMeta(u8 index, u8 x, u8 y, u8 base, u8 planes)
{
	const u8* rec = g_PlayerSprites_Layout + ((u16)base * 2);
	for(u8 i = 0; i < planes; ++i)
	{
		u8 plane = base + i;
		u8 px = x + rec[0];
		u8 py = y + rec[1];
		rec += 2;
		VDP_SetSpriteSM1(index + i, px, py, plane * 4, g_PlayerSprites_Colors[plane]);
	}
}
